-- İHA Tasarım Süreci (T3 10.x) transkriptleri: 9R_trq9J1k8 (10.1), zJ_C_IDZSd0 (10.2), 7m321j6kAv4 (10.3), ua90fzH4a60 (10.4), ixcp84KIM6c (10.5), F5KBs91IJto (10.6).
-- Kaynak: oynatıcının otomatik Türkçe altyazısı (hızlı oynatılıp toplandı; ASR hataları olabilir).
-- Her sorunun kaynak video id ve altyazıdan alıntısı aşağıdaki yorumlardadır (zaman damgası yok: altyazı oynatma sırasında toplandı).
-- İHA Tasarım Süreci orta/zor quizlerine EKLENİR. Idempotent: aynı soru metni varsa atlanır.

begin;

-- 9R_trq9J1k8 kaynak: Tasarıma başlarken ilk olarak hedefimizi belirlemeliyiz. Bu hedeflere dayalı olarak performans parametrelerini netleştirmeliyiz. Sonrasında konsept tasarım... elektronik bileşenleri seçmeliyiz... entegrasyon ve genel sistem tasarımı ile kavramsal tasarım... üretim süreci.
-- zJ_C_IDZSd0 kaynak: Teknofest gibi yarışmalar için bir İHA tasarlamak istiyorsanız bu eğitimde belirlediğimiz hedefler haricinde yarışmanın kendi isterlerini de göz önünde bulundurarak hedeflerinizi belirlemelisiniz.
-- 7m321j6kAv4 kaynak: Bir hava aracının çizimleri doğrudan bilgisayar ortamında oluşturulmaz. Öncelikle aracın konsept tasarımının belirlenmesi gerekir. Konsept çizimlerde kanat, gövde, kuyruk ve motor gibi temel yapılar ve yerleşimleri netleştirilir.
-- ua90fzH4a60 kaynak: NEO M8N GPS modülü: pusula sensörü içermesi ve konum hassasiyetinin sabit kanat İHA'lar için yeterli olması. Servoların seçimi maruz kaldıkları yüke göre belirlenir. Bas çevir acil durdurma butonu. Voltaj akım sensörü: batarya seviyesini yer kontrol istasyonundan anlık takip.
-- ixcp84KIM6c kaynak: Sistem mimarisi bileşenlerin etkileşimini görsel olarak sunarak dışarıdan bir gözlemci için sistemin daha kolay anlaşılmasını sağlar. Devre şemasının merkezinde uçuş kontrol kartımız bulunmakta.
-- F5KBs91IJto kaynak: Kanat profillerinin taşıma katsayısı ve sürükleme katsayısı gibi grafiklerini incelemek için XFLR5 veya Ansys gibi programlardan veya ilgili web sitelerinden faydalanabilirsiniz.
-- F5KBs91IJto kaynak: GPS'imizin düz bir zemine konumlanması çok önemliydi. Bu yüzden hemen kanadın arka kısmında bulunan düz bölgeye GPS'i konumlandırmayı planlıyoruz. Acil durdurma butonunu kanadın orta kısmına, kolay ulaşılabilir olması için.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'İHA Tasarım Süreci' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: İHA Tasarım Süreci orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videodaki yol haritasına göre İHA tasarım adımlarının sırası hangisidir?","a":"Yol haritası, kaosu önlemek için hedeften üretime giden adım adım bir plandır.","o":[["Hedef, performans parametreleri, konsept tasarım, elektronik bileşen seçimi, entegrasyon ve kavramsal tasarım, üretim",true],["Konsept tasarım, hedef, elektronik seçimi, performans parametreleri, üretim",false],["Elektronik bileşen seçimi, konsept tasarım, hedef, üretim",false],["Üretim, hedef, konsept tasarım, performans parametreleri",false]]},{"m":"Yarışmaya yönelik bir İHA tasarlanırken hedefler nasıl belirlenmelidir?","a":"Videodaki hedef, pilotaj eğitimlerinde ve yarışma faaliyetlerinde kullanılabilecek bir İHA tasarlamaktır.","o":[["Yarışmanın kendi isterleri de göz önünde bulundurularak",true],["Yalnızca en ucuz bileşenlere göre",false],["Hedef belirlemeden doğrudan çizime başlanarak",false],["Yalnızca pilotun tercihine göre",false]]},{"m":"Konsept tasarım aşamasında ne yapılır?","a":"Bu çizimler sonraki bilgisayar destekli tasarım için rehber olur ve eksikleri erken fark ettirir.","o":[["Kanat, gövde, kuyruk ve motor gibi temel yapılar ve yerleşimleri netleştirilir; çizimler el çizimleriyle başlar",true],["Doğrudan bilgisayarda ayrıntılı CAD çizimi yapılır",false],["Yazılım yüklenir",false],["Yalnızca elektronik bileşenler seçilir",false]]},{"m":"Videoda voltaj-akım sensörünün işlevi nedir?","a":"GPS modülünün seçimi pusula içermesi ve yeterli konum hassasiyeti, servo seçimi ise yüke göre yapılır.","o":[["İHA'nın çektiği akımı ve batarya voltajını anlık ölçüp yer kontrol istasyonundan batarya seviyesinin izlenmesini sağlar",true],["Motor devrini ölçer",false],["Konumu belirler",false],["Kumanda sinyalini güçlendirir",false]]},{"m":"Videoya göre sistem mimarisi ve devre şemasının amacı nedir?","a":"Devre şemasında diğer bileşenler uçuş kontrol kartının etrafında yer alır.","o":[["Mimari bileşenlerin etkileşimini görsel sunar; devre şeması teknik uygunluğu, güvenliği ve çalışma prensibini değerlendirmeyi sağlar (merkezde uçuş kontrol kartı bulunur)",true],["Yalnızca parça listesi çıkarmak",false],["Yalnızca üretim maliyetini hesaplamak",false],["Kodlama dilini belirlemek",false]]},{"m":"Videoya göre kanat profili seçimi için hangi veriler ve araçlar kullanılır?","a":"Videoda bu grafikler üzerinden değerlendirme yapılıp NACA 2412 profili tercih edilir.","o":[["Profillerin taşıma (CL) ve sürükleme (CD) katsayısı grafikleri; XFLR5, Ansys veya profil web siteleri",true],["Yalnızca el çizimleri",false],["Yalnızca motor test verileri",false],["Pilotun görsel tercihi",false]]},{"m":"Videodaki tasarımda GPS ve acil durdurma butonu nereye yerleştirilmiştir?","a":"GPS'in düz bir zemine konumlanması önemlidir.","o":[["GPS kanadın arkasındaki düz bölgeye, acil durdurma butonu kolay ulaşım için kanadın orta kısmına",true],["GPS kuyruğun ucuna, buton gövdenin altına",false],["GPS bataryanın üstüne, buton kuyruğa",false],["Her ikisi de motorun yanına",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

-- zJ_C_IDZSd0 kaynak: manuel, yarı otonom ve tam otonom uçuş yeteneklerine sahip olmalıdır. Uçuş süresinin 8 ila 10 dakika arasında olması bizim için yeterlidir. En az 10 m/s hızla seyir yapmasını hedefliyoruz. Aracın ağırlığını ise 800 ila 900 gram aralığında tutmayı planlıyoruz.
-- zJ_C_IDZSd0 kaynak: bu parametrelerin sayısı ve türü hedeflerimize ve ihtiyaçlarımıza bağlı olarak değişiklik gösterebilir.
-- 7m321j6kAv4 kaynak: Kanat geometrisi: dikdörtgen, ok açılı ve delta. Aerodinamik verim, üretim kolaylığı ve düşük hız performansı kriterleri; üretim kolaylığı en önemli faktör olduğu için katsayısı 3, diğerleri 2. Sonuçta dikdörtgen kanat öne çıktı.
-- 7m321j6kAv4 kaynak: Geleneksel kuyruk, V kuyruk ve T kuyruk... stabilite, üretim kolaylığı, dayanım ve aerodinamik verim... eşit derecede önemli gördüğümüz için her birini aynı katsayıyla değerlendirdik... geleneksel kuyruk en yüksek puanı aldı.
-- 7m321j6kAv4 kaynak: geleneksel kuyruk yüzeylerinde irtifa dümeni ve yön dümeni... Kanat uçlarında ise kanatçıklar... flap gibi ikincil kontrol yüzeylerini kullanmayacağız.
-- 7m321j6kAv4 kaynak: Kanatların tek parça ve gövdeden ayrık olması daha sağlam ve pratik olacağından ortadan kanat seçeneğini eledik. Taşınabilirlik ve kolay kurulum... üstten kanat... daha stabil bir yapı.
-- 7m321j6kAv4 kaynak: Motor arkasına türbülanslı hava gönderir... T kuyruk tasarımının tercih edilme sebeplerinden biri de budur. Önden motorlu hava araçları hızlandırılmış havayı doğrudan kanat ve kuyruk yüzeylerine yönlendirir; taşıma kuvveti artar ve kontrol yüzeylerinin etkinliği yükselir.
-- ua90fzH4a60 kaynak: tahmini uçuş süresi batarya kapasitesinin aracın çektiği toplam akım miktarına bölünüp 60 ile çarpılarak hesaplanır. Motorumuz maksimum 20.66 amper akım çekiyor. 8 dakikalık uçuş hedefine 2746 miliamper kapasitesinde bir batarya ile ulaşabiliriz.
-- ua90fzH4a60 kaynak: motorumuzun çalışma voltajı 11.1 volt olduğu için bataryanın da aynı voltaj değerine sahip olması gerekiyor. Hesapladığımız kapasiteye en yakın değerde olan 11.1 volt 2800 miliamper 40C lityum polimer batarya modelini tercih ettik.
-- ua90fzH4a60 kaynak: ESC amper değerinin motorun çektiği maksimum akım değerinden daha fazla seçilmesinde fayda vardır. Motor maksimum 20.66 amper çekiyor. Bu nedenle 30 amper ve 3S bataryamız ile uyumlu bir ESC.
-- ua90fzH4a60 kaynak: Sabit kanat İHA'nın kumandadan alması gereken en temel komutlar itki, yunuslama, sapma, yatış ve mod değişikliği. Bu komutları kontrol edebilmek için en az 5 kanala sahip kumanda gereklidir.
-- F5KBs91IJto kaynak: Seyir uçuşunda taşıma kuvveti ağırlığa eşit olmalıdır... hesaplamaları 1 kilogram üzerinden yapalım... en verimli hücum açısı 5 derece, CL 0.8... hava yoğunluğu 1.225... seyir hızı 10 m/s... kanat alanı 0.216 m².
-- F5KBs91IJto kaynak: Aspect ratio kanat açıklığının karesinin kanat alanına bölünmesiyle elde edilir... Yüksek aspect ratio uzun menzil ve yüksek aerodinamik verimlilik sağlar, planörler gibi. Düşük ratio yüksek hız ve manevra kabiliyeti için uygundur, savaş uçakları gibi.
-- F5KBs91IJto kaynak: 0.18 metre uzunluğa ve 1.2 metre genişliğe sahip bir kanat tasarımı belirledik. Bu tasarım 6.6 aspect ratio oranına sahip.
-- F5KBs91IJto kaynak: ağırlık moment tablosu... referans noktası uçağın burun kısmı... her bileşenin kütlesini ve referans noktaya göre uzaklıklarını... moment... kanadın momentini ekleyerek... formülde tek bilinmeyen ağırlık merkezinin uzaklığı.
-- F5KBs91IJto kaynak: Bataryamız için boyutundan biraz daha büyük yer bıraktık. Çünkü olası ağırlık merkezindeki sapmaları bataryayı kaydırarak dengeleyebileceğiz.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'İHA Tasarım Süreci' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: İHA Tasarım Süreci zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoda belirlenen performans parametreleri hangileridir? (birden çok)","a":"Parametrelerin sayısı ve türü hedeflere ve ihtiyaçlara bağlı olarak değişebilir.","o":[["Manuel, yarı otonom ve tam otonom uçuş yeteneği",true],["8-10 dakika uçuş süresi",true],["En az 10 m/s seyir hızı",true],["800-900 gram ağırlık",true]]},{"m":"Performans parametrelerinin sayısı ve türü için videoda ne söylenir?","a":"Aynı görev için bile hedefler değişirse parametreler de değişir.","o":[["Hedeflere ve ihtiyaçlara bağlı olarak değişebilir",true],["Her İHA için sabittir",false],["Yalnızca ağırlık ve hızdan oluşur",false],["Yarışma kuralları belirler, tasarımcı değiştiremez",false]]},{"m":"Videoda kanat geometrisi seçimi nasıl yapılmıştır?","a":"Kanat köpükten yapılacaktır: hafif, ekonomik ve kolay üretilebilir.","o":[["Kriterlere ağırlık katsayısı verilerek (üretim kolaylığı 3, diğerleri 2) puanlanmış ve dikdörtgen kanat seçilmiştir",true],["Delta kanat en yüksek hız verdiği için seçilmiştir",false],["Ok açılı kanat en ucuz olduğu için seçilmiştir",false],["Kriter belirlenmeden deneme yanılmayla seçilmiştir",false]]},{"m":"Videodaki kuyruk seçiminde hangisi doğrudur?","a":"Kuyruk üretiminde düz ve dayanıklı yapısı nedeniyle fotoblok kullanılması planlanmıştır.","o":[["Geleneksel, V ve T kuyruk eşit katsayılı kriterlerle değerlendirilmiş ve geleneksel kuyruk seçilmiştir",true],["T kuyruk en stabil olduğu için seçilmiştir",false],["V kuyruk en az parça gerektirdiği için seçilmiştir",false],["Kuyruk hiç kullanılmamıştır",false]]},{"m":"Videodaki İHA'nın kontrol yüzeyleri ve flap ile ilgili kararı nedir?","a":"Bu yapı yatış, yunuslama ve sapma hareketlerinin kontrolünü sağlar.","o":[["İrtifa dümeni, yön dümeni ve kanatçık kullanılır; gereksiz karmaşıklıktan kaçınmak ve pist mesafesi yeterli olduğu için flap kullanılmaz",true],["Flap, kalkış performansı için zorunlu görülür ve eklenir",false],["Yalnızca kanatçık kullanılır",false],["Kontrol yüzeyi kullanılmaz, motor gücüyle yönlenir",false]]},{"m":"Kanadın gövdeye yerleşiminde videodaki seçim ve gerekçesi nedir?","a":"Kuyruk ise doğrudan gövdenin arkasına, ek bağlantı elemanı olmadan monte edilir.","o":[["Üstten kanat; taşınabilirlik, kolay kurulum ve daha stabil yapı sağladığı için (ortadan kanat elenmiştir)",true],["Alttan kanat; iniş takımıyla uyumlu olduğu için",false],["Ortadan kanat; aerodinamik verim için",false],["Yerleşim seçeneği değerlendirilmemiştir",false]]},{"m":"Motorun gövdenin önüne monte edilmesinin videodaki iki etkisi nedir?","a":"Tek motor tercihinin nedeni, çoklu motorun montaj ve ek maliyet getirmesidir.","o":[["Arkasındaki yapılara türbülanslı hava gönderir; ama havayı hızlandırarak kanat ve kuyruğun taşıma ve kontrol etkinliğini artırır",true],["Hem türbülans hem hızlanmayı yok eder",false],["Yalnızca ağırlık merkezini öne alır",false],["Yalnızca gürültüyü azaltır",false]]},{"m":"Videoda batarya kapasitesi nasıl hesaplanmıştır?","a":"Hesap maksimum gaz seviyesine göre yapılmıştır; seyir gazında uçuş süresi uzayabilir.","o":[["Uçuş süresi = kapasite / toplam akım x 60 formülüyle; 8 dakika hedefi ve yaklaşık 20,66 A maksimum akım için yaklaşık 2746 mAh bulunmuştur",true],["Uçuş süresi = kapasite x akım; 12 V için hesaplanmıştır",false],["Yalnızca bataryanın ağırlığına göre seçilmiştir",false],["Kapasite rastgele seçilmiştir",false]]},{"m":"Videoda hangi batarya seçilmiştir ve voltajı neye göre belirlenmiştir?","a":"Hesaplanan kapasiteye en yakın standart model seçilmiştir.","o":[["11,1 V, 2800 mAh, 40C LiPo; voltaj motorun çalışma voltajıyla aynı olmalıdır",true],["14,8 V, 5000 mAh, 20C LiPo; en yüksek kapasite için",false],["7,4 V, 2800 mAh; ESC'ye uyum için",false],["22,2 V, 4000 mAh; menzil için",false]]},{"m":"ESC seçiminde videodaki kural ve seçim nedir?","a":"ESC seçiminde bataryanın voltajı ve motorun çektiği akım belirleyicidir.","o":[["ESC'nin amper değeri motorun maksimum akımından yüksek olmalı; 20,66 A için 30 A, 3S uyumlu ESC seçilmiştir",true],["ESC amper değeri motorun akımına eşit olmalıdır",false],["ESC seçimi motor ağırlığına göre yapılır",false],["ESC amper değeri önemsizdir",false]]},{"m":"Videoya göre sabit kanat İHA için en az kaç kanallı kumanda gerekir ve neden?","a":"Projede 6 kanallı, 2,4 GHz kumanda kullanılmıştır.","o":[["En az 5 kanal: itki, yunuslama, sapma, yatış ve mod değişikliği komutları için",true],["En az 2 kanal: yalnızca gaz ve yön için",false],["En az 8 kanal: kamera ve LED için",false],["Kumanda kanal sayısı önemli değildir",false]]},{"m":"Videoda kanat alanı hesabı hangi ilke ve değerlerle yapılmıştır?","a":"800-900 g hedefi, üretimden kaynaklanan kayıplar düşünülerek 1 kg üzerinden hesaplanmıştır.","o":[["Seyirde taşıma = ağırlık; kayıplar için 1 kg alınarak, CL = 0,8 (5° hücum açısı), hava yoğunluğu 1,225 kg/m³ ve 10 m/s hızla alan 0,216 m² bulunmuştur",true],["Taşıma ağırlıktan çok küçük alınmış, CL = 2 kullanılmıştır",false],["Alan, motor itkisine göre hesaplanmıştır",false],["Alan deneme yanılmayla belirlenmiştir",false]]},{"m":"Videoya göre en-boy oranı (aspect ratio) nasıl hesaplanır ve yüksek/düşük değerler neyi sağlar?","a":"Öncelik verimlilik olduğundan videoda 6-7 arası en-boy oranı hedeflenmiştir.","o":[["Açıklığın karesi / kanat alanı; yüksek: uzun menzil ve verim (planör), düşük: yüksek hız ve manevra (savaş uçağı)",true],["Veter / açıklık; yüksek: manevra, düşük: menzil",false],["Alan / açıklık; yüksek değer hızı artırır",false],["Açıklık x veter; değerin etkisi yoktur",false]]},{"m":"Kanat açıklığı 1,2 m ve kanat alanı 0,216 m² ise en-boy oranı yaklaşık kaçtır?","a":"AR = 1,2² / 0,216 ≈ 6,7. Videoda 0,18 m veter ve 1,2 m açıklıkla yaklaşık 6,6 bulunmuştur.","o":[["3,3",false],["6,7",true],["12",false],["0,18",false]]},{"m":"İHA'nın ağırlık merkezi videoda nasıl bulunur?","a":"Ağırlık merkezi bulunduktan sonra kanadın yerleşim konumu buna göre ayarlanır.","o":[["Ağırlık-moment tablosuyla: burun referans alınır, her bileşenin kütle x uzaklık momenti hesaplanır, kanadın momenti eklenir ve tek bilinmeyen olan ağırlık merkezi uzaklığı çözülür",true],["Aracı ipte asarak denenir",false],["Yalnızca motorun konumu ölçülür",false],["Bataryanın ağırlığı kullanılır",false]]},{"m":"Tasarımda batarya yuvası neden bataryanın boyutundan biraz büyük bırakılmıştır?","a":"Batarya, ağırlık merkezi ayarında en kolay kaydırılabilen kütledir.","o":[["Ağırlık merkezindeki olası sapmaları bataryayı kaydırarak dengelemek için",true],["Bataryanın soğuması için",false],["Daha büyük batarya takabilmek için",false],["Titreşimi artırmak için",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

commit;
